def vigenere_cipher(text, keyword):
    result = ""

    # Convert the keyword to lowercase and repeat it according to the length of the text
    keyword = keyword.lower()
    keyword = keyword * (len(text) // len(keyword)) + keyword[:len(text) % len(keyword)]

    for i in range(len(text)):
        char = text[i]
        if char.isalpha():
            shift = ord(keyword[i]) - 97 if char.islower() else ord(keyword[i]) - 65
            if char.islower():
                result += chr((ord(char) - 97 + shift) % 26 + 97)
            else:
                result += chr((ord(char) - 65 + shift) % 26 + 65)
